#include "kstationNativeController.h"
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <new>
#include <vector>
namespace {bool watch=false;unsigned allocations=0;void check(bool p,const char*m){if(!p)throw std::runtime_error(m);}}
void*operator new(size_t n){if(watch)++allocations;if(auto*p=std::malloc(n?n:1))return p;throw std::bad_alloc();}void*operator new[](size_t n){return ::operator new(n);}void operator delete(void*p)noexcept{std::free(p);}void operator delete[](void*p)noexcept{std::free(p);}void operator delete(void*p,size_t)noexcept{std::free(p);}void operator delete[](void*p,size_t)noexcept{std::free(p);}
int main(int argc,char**argv){try{if(argc!=2)return 77;std::ifstream in(argv[1],std::ios::binary);std::vector<uint8_t>image{std::istreambuf_iterator<char>(in),{}};unsigned group=0;kstation::ControllerHostCallbacks host{[&](uint32_t a){if(a==14)group=2;return uint8_t(a==4?(group==1?16:7):0);},[&](uint32_t a,uint8_t v){if(a==0&&v==8)group=1;if(a==14)group=2;return true;},[&](bool asserted){if(asserted)group=0;}};kstation::NativeController native(image,host);check(native.isNative(),"Native backend identity");check(!native.exec(0),"Zero budget consumed clocks");bool rejected=false;try{(void)native.core();}catch(const std::logic_error&){rejected=true;}check(rejected,"Native backend exposed architectural CPU");watch=true;for(unsigned i=0;i<1000;++i)check(native.exec(128)>=128,"Native early boot made no progress");watch=false;check(!allocations,"Native early processing allocated");auto first=native.debugState();check(first.instructions&&first.interpretedSteps==0&&!first.mainEntered&&!native.bootReady(),"Early boot state");native.reset();check(native.debugState().cycles==0,"Independent full reset");watch=true;for(unsigned i=0;i<1000;++i)native.exec(128);watch=false;auto second=native.debugState();check(first.cycles==second.cycles&&first.instructions==second.instructions&&!allocations,"Native reset determinism");kstation::NativeController faulty(image,host);bool overlay=false;for(unsigned i=0;i<200000&&!overlay&&!faulty.faultMessage();++i){watch=true;faulty.exec(128);watch=false;overlay=faulty.debugState().ramOverlay;}if(!overlay||faulty.faultMessage()||allocations)std::fprintf(stderr,"overlay=%d cycles=%llu fault=%s allocations=%u bindings=%u\n",overlay,faulty.debugState().cycles,faulty.faultMessage()?faulty.faultMessage():"none",allocations,faulty.immutableBindingCount());check(overlay&&!faulty.faultMessage()&&!allocations,"Pre-DSP overlay did not settle");auto bindings=faulty.immutableBindingCount();
 faulty.diagnosticWrite16(37*4,0xffff);faulty.diagnosticWrite16(37*4+2,0xffff);faulty.diagnosticInterrupt(37);watch=true;for(unsigned i=0;i<10000&&!faulty.faultMessage();++i)faulty.exec(128);auto stopped=faulty.exec(128);watch=false;check(faulty.faultMessage()&&stopped==0&&!allocations,"Nonallocating vector-fault latch failed");check(std::string(faulty.faultMessage())=="first IRQ body interval","Unexpected fault in vector rejection test");faulty.reset();check(!faulty.faultMessage(),"Fault survived independent reset");
  std::printf("{\"passed\":true,\"early_boot_cycles\":%llu,\"early_boot_phases\":%llu,\"reset_exact\":true,\"linked_h8_sources\":false,\"processing_allocations\":%u,\"full_boot_proven\":false,\"nonallocating_fault_latch\":true,\"resource_bindings_before_dsp\":%u}\n",first.cycles,first.instructions,allocations,bindings);return 0;}catch(const std::exception&e){watch=false;std::fprintf(stderr,"FAIL:%s\n",e.what());return 1;}}
